const fs = require('fs');
const dir = process.argv[2];
const target = process.argv[3];
const lines = fs.readFileSync(dir + '/orig.md', 'utf8').split('\n');
const reps = fs.readdirSync(dir).filter(f => /^r\d+_\d+\.txt$/.test(f)).map(f => {
  const m = f.match(/^r(\d+)_(\d+)\.txt$/);
  return { s: +m[1], e: +m[2], f };
}).sort((a, b) => b.s - a.s);
// overlap check
const asc = [...reps].reverse();
for (let i = 1; i < asc.length; i++) if (asc[i].s <= asc[i - 1].e) throw new Error('overlap ' + asc[i - 1].f + ' ' + asc[i].f);
for (const r of reps) {
  let txt = fs.readFileSync(dir + '/' + r.f, 'utf8').replace(/\r\n/g, '\n').replace(/\n$/, '');
  lines.splice(r.s - 1, r.e - r.s + 1, ...txt.split('\n'));
}
fs.writeFileSync(target, lines.join('\n'));
console.log('replaced', reps.length, 'ranges; lines now', lines.length);

